type Orders struct{ items []Order }              // unexported: no aliasing leak

func New(items ...Order) Orders { return Orders{items: slices.Clone(items)} }

func (o *Orders) Add(order Order) error {
    if len(o.items) >= MaxOrders {
        return ErrOrderLimit
    }
    o.items = append(o.items, order)
    return nil
}

func (o Orders) All() []Order { return slices.Clone(o.items) }  // caller may sort it
